const {vec} = NMath;
const {vertices} = await IO.loadMesh("/assets/bunny.obj");

let pts = vertices.map(vertex => vec(...vertex));
const normalizeVectors = vectors => {
    const mean = vectors.reduce((sum, value) => sum.add(value), vec.zero(3)).scale(1 / vectors.length);
    const centered = vectors.map(value => value.sub(mean));
    const max = centered.reduce((largest, value) => Math.max(largest, value.map(Math.abs).fold(0, (a, x) => Math.max(a, x))), 0);
    const scaled = max === 0 ? centered : centered.map(value => value.scale(1 / max));
    return scaled.map(({components: [x, y, z]}) => vec(z, x, y));
};
pts = normalizeVectors(pts);

const graph = Graph.knn(pts, 4, (x, y) => x.sub(y).length());
const laplacian = graph.laplacian((i, j) => Math.exp(-i.vertex.dot(j.vertex) / 10));
const k = Math.min(16, pts.length);
const {eigenvectors} = laplacian.eigen({maxFirst: false, k});
const clamp = x => Math.min(1, Math.max(0, x));
const r = 10 / 4;
const colors = eigenvectors.map(eigenvector => {
    const max = eigenvector.fold(Number.NEGATIVE_INFINITY, (value, x) => Math.max(value, x));
    const min = eigenvector.fold(Number.POSITIVE_INFINITY, (value, x) => Math.min(value, x));
    const range = max - min;
    const isConstant = range < 0.05 * Math.max(Math.abs(max), Math.abs(min));
    return eigenvector.toArray().map(value => {
        const x = isConstant ? 0.5 : (value - min) / range;
        return [clamp(r * x), clamp(r * (x - 0.4)), clamp(5 * (x - 0.8))];
    });
});
const points = pts.map(point => point.toArray());
const plot = IO.plotPointCloud(points, {color: colors[0]});
const updateEigenvector = index => {
    plot.update(points, {color: colors[index]});
    plot.render();
};
const ui = IO.UI(
    {type: "canvas", value: () => plot},
    {type: "slider", value: () => ({
        min: 0,
        max: colors.length - 1,
        step: 1,
        value: 0,
        title: "Eigenvector:",
        onChange: value => updateEigenvector(Math.round(value)),
    })},
);
ui;
